import type { ConditionalQuestion, ConditionalUnit } from './types';

// Original LSAT U teaching and exercises. Design references, not copied banks:
// ai-os/brainstorms/2026-09-30-conditional-curriculum/curriculum-analysis.md;
// research-7sage-lr.md; research-lsatlab-core-class.md;
// research-lsatlab-advanced-conditionals.md; research-lsatlab-quantifiers.md.
// Question tuples carry prompt, correct answer, distractors, explanation and hint.
type Exercise = [string, string, string, string, string, string];
function question(unit: string, band: string, index: number, e: Exercise): ConditionalQuestion {
  const answerIndex = index % 3;
  const options = [e[2], e[3]];
  options.splice(answerIndex, 0, e[1]);
  return { id: `${unit}-${band}-${index + 1}`, prompt: e[0], options, answerIndex,
    explanation: e[4], hint: e[5], reasoningSteps: [e[5], ...e[4].split(/(?<=[.!?])\s+/)] };
}
type Draft = Omit<ConditionalUnit, 'drills' | 'guidedExample'> & { guided: Exercise; practice: Exercise[] };
function unit(d: Draft): ConditionalUnit {
  const { guided, practice, ...content } = d;
  return { ...content, guidedExample: question(d.id, 'guided', 0, guided), drills: {
    beginner: practice.slice(0, 3).map((e, i) => question(d.id, 'beginner', i, e)),
    medium: practice.slice(3, 6).map((e, i) => question(d.id, 'medium', i, e)),
    advanced: practice.slice(6, 9).map((e, i) => question(d.id, 'advanced', i, e)),
  } };
}

